 screens=[{'id':'welcome','title':'یک شروع تازه','description':'گرافیک زنده، واکنش به شروع و گفت‌وگوی بدون شلوغی.','png':'screen-welcome.png'}, {'id':'consent','title':'پذیرش کوتاه و روشن','description':'متن کامل قوانین پشت لینک؛ اجازهٔ تماس جدا و اختیاری.','png':'screen-consent.png'}, {'id':'home','title':'خانهٔ همراه شما','description':'وضعیت واقعی پرونده و قدم بعدی پس از انتشار پزشک.','png':'screen-home.png'}, {'id':'program','title':'برنامه و قدم‌های من','description':'جمع‌بندی پزشک و ثبت انجام در همان مسیر اقدام‌ها.','png':'screen-program.png'}, {'id':'form','title':'شروع از دلیل مراجعهٔ شما','description':'شش مسیر، اولویت کاربر و هدف‌گذاری پیش از تشکیل برنامه.','png':'screen-form.png'}, {'id':'payment','title':'پرداخت نمایشی و رسید','description':'مرور سفارش، نتیجهٔ پرداخت و رسید قابل پیگیری.','png':'screen-payment.png'}, {'id':'doctor','title':'میز بررسی پزشک','description':'پروندهٔ تخصیص‌یافته، بررسی و اقدام‌های بعدی.','png':'screen-doctor.png'}, {'id':'coordinator','title':'میز هماهنگی کارشناس','description':'درخواست‌های ارجاعی و ثبت نتیجهٔ هماهنگی.','png':'screen-coordinator.png'}]
 assets={}
 for item in screens+diagrams:assets[item['id']]={**item,'png':'presentation/assets/'+item['png'],**({'svg':'presentation/assets/'+item['svg']} if 'svg' in item else {})}
