 def link(label,url,cls='button primary',ico='arrow'):return f'<a class="{cls}" href="{url}">{label}{icon(ico)}</a>'
 def heading(kicker,title,desc):return f'<div class="section-heading"><p class="eyebrow">{kicker}</p><h2 tabindex="-1">{title}</h2><p>{desc}</p></div>'
 def image_card(item,group=''):
  key=item['id'];kind='طرح هدف' if item.get('status')=='target' else 'کد سروری موجود' if item.get('status')=='server' else 'نسخهٔ نمایشی' if 'status' in item else 'تصویر نمونه'
  return f'<article class="visual-card" data-group="{group}"><button class="visual-open" data-view="{key}" aria-label="بزرگ‌نمایی {item["title"]}"><img src="{assets[key]["png"]}" alt="{item["title"]}" loading="lazy"><span class="enlarge">{icon("image")} بزرگ‌نمایی</span></button><div class="visual-copy"><span class="badge {"amber" if item.get("status")=="target" else "soft"}">{kind}</span><h3>{item["title"]}</h3><p>{item["description"]}</p><div class="visual-links"><button data-view="{key}">مشاهدهٔ تصویر {icon("arrow")}</button>'+ (f'<a href="{assets[key]["png"]}" download>PNG</a><a href="{assets[key]["svg"]}" download>SVG</a>' if 'svg' in item else '')+'</div></div></article>'
 body='<a class="skip" href="#main">رفتن به محتوا</a><div class="dashboard"><aside class="sidebar"><a class="brand" href="#overview">'+mark+'<span>سلامت‌بان<small>معرفی و بررسی محصول</small></span></a><p class="nav-caption">مسیر آشنایی</p><nav aria-label="بخش‌های داشبورد">'
