 body+='<section id="experience" class="pane"><div class="inline-note"><p><strong>نقشهٔ جامع مسیر کاربر</strong> · <a href="presentation/assets/user-flow/index.html">باز کردن فلوچارت تصویری و بزرگ‌نمایی</a><br>این تصویر طرح هدف کامل است؛ محدودهٔ اجراشدهٔ نسخهٔ ۲٫۱ در راهنمای محصول مشخص شده است.</p></div>'+heading('چند دقیقه با محصول','مسیر هر نقش را امتحان کنید','یک پرونده را در همان مرورگر دنبال کنید؛ خروج از حساب، دادهٔ نمونه را پاک نمی‌کند.')+'<div class="role-tabs" role="group" aria-label="انتخاب نقش">'
 roles=[('member','عضو','09000000001',['با حساب عضو وارد شوید؛ کد نمایشی پس از درخواست روی صفحه است.','شروع آشنایی را بزنید؛ دلیل مراجعه، هدف، مشخصات و پاسخ‌های نمونه را ثبت کنید.','پرداخت نمایشی و سپس ارسال پرونده را انجام دهید.','برنامه و نتیجهٔ هماهنگی را بعد از اقدام تیم ببینید.'],'آیا قدم بعدی و وضعیت پرونده برایتان روشن است؟'),('doctor','پزشک','09000000011',['در همان مرورگر با حساب پزشک وارد شوید.','پروندهٔ تخصیص‌یافته را از صف انتخاب کنید.','اطلاعات بیشتری بخواهید یا جمع‌بندی و برنامه منتشر کنید.','اقدام‌های مربوط به تیم را با رضایت عضو به هماهنگی ارجاع دهید.'],'آیا بررسی پرونده و اقدام بعدی پزشک به اندازهٔ کافی واضح است؟'),('coordinator','کارشناس','09000000012',['ابتدا یک اقدام تیمی از سمت پزشک یا درخواست نوبت از عضو ایجاد کنید.','با حساب کارشناس وارد شوید و درخواست را از صف انتخاب کنید.','مرکز، زمان، مرجع تأیید و رضایت لازم را ثبت کنید.','نتیجهٔ هماهنگی یا انجام اقدام را برای عضو ثبت کنید.'],'آیا درخواست ارجاعی و مراحل هماهنگی قابل فهم است؟'),('admin','مدیر','09000000013',['با حساب مدیر وارد شوید.','اعضا و پزشک مسئول هر عضو را بررسی کنید.','دعوت، تخصیص و تعلیق دسترسی را با دادهٔ ساختگی امتحان کنید.','درخواست پشتیبانی را پاسخ دهید؛ حذف یا بازپرداخت واقعی هنوز اجرا نمی‌شود.'],'آیا مدیریت دسترسی و پیگیری درخواست‌ها روشن است؟')]
 for key,title,phone,steps,prompt in roles:body+=f'<button data-role="{key}" aria-pressed="{str(key=="member").lower()}">{title}</button>'
